INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,包装类,Integer', 1, 'Integer 的缓存机制是什么？为什么 Integer a = 127、b = 127 时 a == b 为 true，而 128 时为 false？', 'Integer.valueOf 会缓存 -128 到 127 之间的对象，所以 127 时 a 和 b 指向同一个缓存对象，== 为 true；128 超出缓存范围会新建对象，== 比较地址为 false。包装类数值比较应使用 equals 或先转成基本类型。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,String,不可变', 1, 'String 为什么设计成不可变？', 'String 内部用 final 修饰的字节数组或字符数组保存内容，并且不提供修改方法，所以对象创建后不可变。不可变带来线程安全、可安全共享、hash 可缓存、适合字符串常量池等好处；频繁拼接应使用 StringBuilder。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,String,常量池,intern', 2, '字符串常量池是什么？new String("abc") 和字面量 "abc" 有什么区别？', '字符串字面量会进入字符串常量池，new String("abc") 会在堆中创建新对象。intern() 会返回常量池中的引用，不存在时先放入常量池。字面量之间 == 通常为 true，new 出来的对象 == 通常为 false，内容比较用 equals。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,重载,重写,多态', 2, '重载和重写有什么区别？', '重载是同一类中方法名相同、参数列表不同，编译期决定调用哪个方法；重写是子类重新实现父类方法，方法签名相同，运行时根据对象实际类型决定。重写不能降低访问权限，不能抛出更宽的受检异常，返回值可以是父类返回值的子类。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,接口,抽象类', 2, '接口和抽象类有什么区别？分别适合什么场景？', '抽象类可以有构造器、成员变量和普通方法，表示 is-a 的继承关系；接口强调能力契约，支持多实现，Java 8 后可以有 default 和 static 方法。需要复用状态和代码时用抽象类，需要定义可组合的能力时用接口。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,值传递', 2, 'Java 是值传递还是引用传递？为什么方法内修改对象会影响外部？', 'Java 只有值传递。基本类型传递的是值的副本；对象传递的是引用地址的副本。方法内可以通过这个引用修改对象内容，但不能让方法外的引用指向新对象，所以看起来像引用传递，本质仍是值传递。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,static', 1, 'static 关键字可以修饰什么？有什么特点？', 'static 可以修饰变量、方法、代码块和内部类，修饰的成员属于类而不是实例，所有对象共享。static 方法不能直接访问实例成员和 this；static 代码块在类初始化时执行一次；static 变量常用来表示全局配置或常量。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,泛型,类型擦除', 2, '什么是泛型类型擦除？擦除后会带来哪些限制？', 'Java 泛型在编译期做类型检查，编译后类型参数会被擦除为 Object 或它的上界，运行时无法获取具体泛型类型。因此不能 new T()、不能对泛型做 instanceof、不能直接创建泛型数组；编译器会生成桥接方法保证多态调用。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,反射', 2, '什么是反射？反射有什么优缺点？', '反射允许程序在运行期获取类的构造器、方法、字段并调用，常见入口有 Class.forName、对象.getClass()、类名.class。Spring、MyBatis 等框架大量使用反射做依赖注入和映射；缺点是性能开销、破坏封装，处理不可信输入时还有安全风险。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,深拷贝,浅拷贝', 2, '深拷贝和浅拷贝有什么区别？如何实现深拷贝？', '浅拷贝只复制对象本身和基本类型字段，引用类型字段仍指向同一对象；深拷贝会递归复制引用对象。可以通过实现 Cloneable 并重写 clone、使用拷贝构造器，或通过序列化实现深拷贝，注意处理循环引用。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,Java8,Lambda,Stream', 1, 'Java 8 有哪些常用新特性？', 'Java 8 引入 Lambda、函数式接口、Stream、方法引用、接口 default 和 static 方法、Optional、新的 Date/Time API 等。Lambda 让行为可以作为参数传递，Stream 提供声明式集合处理，default 方法让接口可以在不破坏实现类的情况下扩展。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,Stream,函数式编程', 2, 'Stream 的中间操作和终端操作有什么区别？为什么说 Stream 是惰性的？', '中间操作包括 filter、map、sorted、distinct，返回新的 Stream；终端操作包括 collect、forEach、reduce、count，触发实际执行。中间操作是惰性的，只有遇到终端操作才会遍历数据；Stream 只能消费一次，适合声明式处理集合。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,Optional,空指针', 2, 'Optional 的作用是什么？使用时有哪些注意事项？', 'Optional 用来表达一个值可能不存在，减少空指针。常用 map、flatMap 做链式转换，orElse、orElseGet、orElseThrow 提供默认值或异常。不要把 Optional 用作字段、方法参数或集合元素，也不要用 isPresent 加 get 代替简单的空判断。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,异常,try-catch-finally', 2, 'try-catch-finally 的执行顺序是什么？finally 中 return 会怎样？', 'try 中发生异常时先执行匹配的 catch，再执行 finally；没有异常时执行完 try 后执行 finally。即使 try 或 catch 中有 return，也会先执行 finally。不要在 finally 中 return 或抛异常，否则会覆盖原来的返回值或异常；Java 7 的 try-with-resources 可以自动关闭资源。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,序列化,transient', 2, '什么是序列化和反序列化？transient 关键字有什么作用？', '序列化把对象转换为字节流，反序列化再恢复对象。类需要实现 Serializable，建议显式声明 serialVersionUID。transient 和 static 字段不会被序列化。反序列化不可信数据存在安全风险，生产环境应做白名单和校验。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,final,finally,finalize', 2, 'final、finally、finalize 有什么区别？', 'final 是修饰符，可以修饰变量、方法和类，表示不可再赋值、不可重写、不可继承；finally 是异常处理块，通常用于释放资源；finalize 是 Object 的方法，GC 前可能调用，但执行时机不确定，JDK 9 后已废弃，不应依赖。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,动态代理,JDK,CGLIB', 3, 'JDK 动态代理和 CGLIB 有什么区别？Spring AOP 如何选择？', 'JDK 动态代理基于接口，通过 Proxy 和 InvocationHandler 在运行期生成代理类；CGLIB 通过继承目标类生成子类，可以代理没有接口的类，但不能代理 final 类和 final 方法。Spring AOP 默认接口使用 JDK 代理，没有接口时使用 CGLIB。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,注解,元注解', 2, '什么是注解？常见元注解有哪些？', '注解是给代码附加元数据的语法，本身不改变程序逻辑，运行时可以通过反射读取。常见元注解有 @Retention 控制保留阶段、@Target 限制使用位置、@Documented 表示包含在文档中、@Inherited 表示可被继承。框架常用注解做配置、路由、事务和校验。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,put', 2, 'HashMap 的 put 流程是怎样的？', '先计算 key 的 hash，把高 16 位和低 16 位异或，再用 (n-1)&hash 定位桶。桶为空直接放入；否则遍历链表或红黑树，key 相同则覆盖，不同则尾插。链表长度超过 8 且容量至少 64 时树化，插入后 size 超过阈值触发扩容。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,扩容,resize', 2, 'HashMap 的扩容机制是什么？JDK 8 扩容时元素如何重新分布？', '默认容量 16、负载因子 0.75，阈值等于容量乘负载因子，超过阈值扩容为原来的 2 倍。JDK 8 扩容时不需要重新计算 hash，元素根据 hash 的新增高位落到原位置或原位置加旧容量，减少迁移成本。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,容量', 2, 'HashMap 的容量为什么必须是 2 的幂？', '容量为 2 的幂时，(n-1)&hash 等价于对 n 取模，但位运算更快；同时能让 hash 的低位更均匀地分布到桶中。因此 HashMap 会把传入容量调整为大于等于它的最小 2 的幂。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,负载因子', 2, 'HashMap 的负载因子为什么默认是 0.75？', '负载因子是空间和冲突率的折中。太小会频繁扩容、浪费空间；太大冲突增多、查询变慢。0.75 在常见场景下兼顾内存利用率和查询性能，是 JDK 选择的默认值。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,红黑树,树化', 2, 'HashMap 什么时候链表转红黑树？为什么阈值是 8 和 6？', '链表长度达到 8 且数组容量至少 64 时转红黑树；容量不足 64 时优先扩容而不是树化。红黑树节点减少到 6 时退化为链表，7 和 8 之间留出缓冲，避免频繁转换。阈值来自哈希冲突概率和性能折中。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashMap,线程安全', 2, 'HashMap 为什么线程不安全？并发场景应该用什么？', 'HashMap 没有并发控制。JDK 7 并发扩容可能形成链表环导致死循环；JDK 8 并发 put 可能丢失数据或覆盖其他线程的修改。多线程场景应使用 ConcurrentHashMap，或者在外层加锁。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,ConcurrentHashMap,分段锁,CAS', 3, 'ConcurrentHashMap 在 JDK 7 和 JDK 8 中的实现有什么区别？', 'JDK 7 使用 Segment 分段锁，每个 Segment 是一个小 HashMap，锁粒度是段；JDK 8 取消 Segment，改用 CAS 加 synchronized 锁桶头节点，锁粒度细化到单个桶，并用 ForwardingNode 支持并发扩容和协助迁移。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,ConcurrentHashMap,null', 2, 'ConcurrentHashMap 为什么不允许 null 键和 null 值？', '并发场景下如果允许 null，无法区分 key 不存在和 value 为 null，get 返回 null 会有歧义；同时也会让并发控制更复杂。HashMap 允许一个 null 键和多个 null 值，但 ConcurrentHashMap 选择禁止。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,ArrayList,扩容', 2, 'ArrayList 的扩容机制是怎样的？', 'ArrayList 默认初始容量是 10，首次添加元素时分配数组；扩容时新容量约为原容量的 1.5 倍，并复制原数组。频繁插入大量元素时可以预设容量，减少扩容和数组复制。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,迭代器,fail-fast,fail-safe', 2, 'fail-fast 和 fail-safe 迭代器有什么区别？', 'fail-fast 迭代器在遍历过程中如果集合被结构性修改，会抛 ConcurrentModificationException，例如 ArrayList、HashMap；fail-safe 迭代器遍历的是快照或弱一致视图，不会抛该异常，例如 CopyOnWriteArrayList、ConcurrentHashMap。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,HashSet,hashCode,equals', 2, 'HashSet 是如何保证元素不重复的？', 'HashSet 内部用 HashMap 存储，元素作为 key，value 是固定对象。添加时先比较 hashCode 定位桶，再用 equals 判断是否重复。因此自定义对象作为元素时必须正确重写 hashCode 和 equals。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,LinkedHashMap,LRU', 3, 'LinkedHashMap 如何实现 LRU 缓存？', 'LinkedHashMap 在 HashMap 基础上维护双向链表，默认按插入顺序；构造时设置 accessOrder 为 true 可以按访问顺序排列。重写 removeEldestEntry 可以在超过容量时删除最久未访问的元素，从而实现简单的 LRU 缓存。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,TreeMap,TreeSet,红黑树', 2, 'TreeMap 和 TreeSet 的底层结构是什么？如何实现排序？', 'TreeMap 基于红黑树，按 key 排序，支持元素实现 Comparable 或构造时传入 Comparator；TreeSet 基于 TreeMap。它们的查找、插入、删除平均为 O(log n)，适合范围查询和排序场景，是否允许 null 取决于比较器。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,CopyOnWriteArrayList,读写分离', 3, 'CopyOnWriteArrayList 的原理是什么？适合什么场景？', '写操作会复制一份新数组并在新数组上修改，读操作无锁，适合读多写少的场景，例如监听器列表。缺点是写入开销大、内存占用高，迭代器只能看到创建时的快照，属于弱一致性。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,BlockingQueue,生产者消费者', 2, '常见的 BlockingQueue 有哪些？分别适合什么场景？', '常见实现有 ArrayBlockingQueue（有界数组，适合固定容量）、LinkedBlockingQueue（链表，可有界或无界）、SynchronousQueue（不存储元素，直接交接）、PriorityBlockingQueue（按优先级出队）、DelayQueue（延迟到期才能取出）。它们常用于生产者-消费者和线程池任务队列。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 集合', '校招', 'Java,集合,PriorityQueue,堆', 2, 'PriorityQueue 的底层原理是什么？它保证遍历有序吗？', 'PriorityQueue 基于二叉堆，默认小顶堆，出队顺序按优先级而不是插入顺序；可以通过 Comparator 自定义排序。它不保证遍历有序，peek 和 poll 的时间复杂度是 O(log n)，适合 TopK、任务调度等场景。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程,生命周期', 2, 'Java 线程有哪些状态？状态之间如何流转？', 'Java 线程状态有 NEW、RUNNABLE、BLOCKED、WAITING、TIMED_WAITING、TERMINATED。BLOCKED 是等待进入 synchronized 临界区；WAITING 是调用 wait、join、park 后无限等待；TIMED_WAITING 是带超时的等待；RUNNABLE 包含正在运行和就绪。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程,创建方式', 1, '创建线程有哪些方式？实际项目推荐哪种？', '常见方式有继承 Thread、实现 Runnable、实现 Callable 配合 Future 或 FutureTask，以及提交任务到线程池；Java 21 还可以使用虚拟线程。实际项目优先使用线程池，避免频繁创建和销毁线程，并统一管理并发度。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,Runnable,Callable,Future', 2, 'Runnable 和 Callable 有什么区别？', 'Runnable 的 run 方法没有返回值，也不能抛出受检异常；Callable 的 call 方法有返回值，并且可以抛出异常，通常配合 Future 或 FutureTask 获取结果。需要结果或异常传播时用 Callable。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,sleep,wait,锁', 2, 'sleep 和 wait 有什么区别？', 'sleep 是 Thread 的静态方法，让当前线程休眠指定时间，不释放锁；wait 是 Object 的方法，必须在 synchronized 块中调用，会释放锁并进入等待，直到 notify、notifyAll 或超时。sleep 不依赖锁，wait 依赖对象监视器。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,synchronized,Monitor', 3, 'synchronized 的底层原理是什么？可以修饰哪些位置？', 'synchronized 基于对象监视器 Monitor 实现互斥和可见性。修饰实例方法锁当前对象，修饰静态方法锁 Class 对象，修饰代码块锁指定对象。字节码层面是 monitorenter 和 monitorexit 或 ACC_SYNCHRONIZED 标记，支持可重入，异常时自动释放锁。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,锁升级,偏向锁,轻量级锁', 3, 'synchronized 的锁升级过程是怎样的？', 'JDK 6 后 synchronized 有偏向锁、轻量级锁、重量级锁等优化，锁状态随竞争升级：无锁、偏向锁、轻量级锁、重量级锁。偏向锁适合只有一个线程反复进入；有竞争时升级为轻量级锁，通过 CAS 自旋；竞争激烈时升级为重量级锁，线程阻塞。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,volatile,可见性,指令重排', 2, 'volatile 能保证什么？不能保证什么？', 'volatile 保证可见性和有序性，不保证原子性。写 volatile 变量会立即刷新到主内存，读会从主内存读取；同时通过内存屏障禁止指令重排。适合状态标志和 DCL 单例的实例引用，不能用于 i++ 这类复合操作。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,JMM,happens-before', 3, 'JMM 是什么？happens-before 有哪些常见规则？', 'JMM 是 Java 内存模型，规定线程如何与主内存交互，核心是可见性、有序性和 happens-before。常见规则包括程序顺序、监视器锁、volatile 读写、线程 start 和 join、final 字段等；如果两个操作存在 happens-before 关系，前一个操作的结果对后一个可见。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,CAS,ABA,原子类', 3, '什么是 CAS？ABA 问题如何解决？', 'CAS 包含内存地址、期望值和新值，只有当前值等于期望值时才更新，通常由 CPU 原子指令实现。ABA 问题是值从 A 改成 B 又改回 A，CAS 无法察觉；可以使用版本号或时间戳，例如 AtomicStampedReference。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,AQS,ReentrantLock', 3, 'AQS 的核心原理是什么？哪些类基于 AQS 实现？', 'AQS 是 JUC 的同步器框架，核心是一个 volatile int state 和一个 FIFO 双向等待队列。线程通过 CAS 修改 state 竞争资源，失败者入队等待，释放时唤醒后继节点；支持独占模式和共享模式。ReentrantLock、Semaphore、CountDownLatch 等都基于 AQS。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,ReentrantLock,synchronized', 2, 'ReentrantLock 和 synchronized 有什么区别？', '两者都可重入，都保证互斥和可见性。synchronized 是 JVM 关键字，自动释放锁，使用简单；ReentrantLock 是 API，需要手动 unlock，支持公平锁、可中断、超时 tryLock 和多个 Condition，功能更灵活但容易忘记释放锁。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,公平锁,非公平锁', 2, '公平锁和非公平锁有什么区别？', '公平锁按等待队列顺序获取锁，避免饥饿但吞吐量较低；非公平锁允许新线程直接抢锁，性能更高但可能让等待线程迟迟拿不到锁。ReentrantLock 默认非公平，synchronized 也是非公平的。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,ThreadLocal,内存泄漏', 3, 'ThreadLocal 的原理是什么？为什么可能造成内存泄漏？', 'ThreadLocal 为每个线程提供独立副本，数据存放在 Thread 的 ThreadLocalMap 中，key 是 ThreadLocal 的弱引用。线程池中线程会复用，如果不调用 remove，value 可能一直存活导致内存泄漏；使用完应调用 remove。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程池,ThreadPoolExecutor', 3, 'ThreadPoolExecutor 的核心参数有哪些？', '核心参数有 corePoolSize、maximumPoolSize、keepAliveTime、unit、workQueue、threadFactory、handler。核心线程常驻，非核心线程空闲超过 keepAliveTime 回收，队列和拒绝策略决定过载行为。参数要结合任务类型、下游容量和压测结果设置。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程池,执行流程', 3, '线程池提交任务后的执行流程是什么？', '提交任务后，如果核心线程未满就创建核心线程执行；核心线程满了进入工作队列；队列满了且线程数未达到 maximumPoolSize 就创建非核心线程；再满则执行拒绝策略。理解这个顺序才能正确设置队列和最大线程数。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程池,拒绝策略', 2, '线程池常见的拒绝策略有哪些？', '常见拒绝策略有 AbortPolicy，抛 RejectedExecutionException，是默认策略；CallerRunsPolicy，由调用线程自己执行；DiscardPolicy，静默丢弃任务；DiscardOldestPolicy，丢弃队列中最老的任务再尝试提交。生产环境应结合业务选择并监控拒绝次数。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,线程池,线程数', 2, '线程池的核心线程数应该如何设置？', 'CPU 密集型任务线程数一般设为 CPU 核数加 1；IO 密集型任务可以设为 CPU 核数的 2 倍或更高，因为线程大部分时间在等待 IO。实际值要结合压测、任务耗时和下游容量调整，不能只套公式。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,CompletableFuture,异步编排', 3, 'CompletableFuture 常用方法有哪些？使用时要注意什么？', 'CompletableFuture 支持异步任务编排，常用 supplyAsync、runAsync 创建任务，thenApply、thenCompose、thenAccept 做转换和串联，exceptionally、handle 处理异常，allOf、anyOf 组合多个任务。默认使用 ForkJoinPool.commonPool，IO 密集型任务建议传入自定义线程池。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,CountDownLatch,CyclicBarrier,Semaphore', 3, 'CountDownLatch、CyclicBarrier、Semaphore 有什么区别？', 'CountDownLatch 是一次性计数器，主线程 await 等待其他线程 countDown 到 0；CyclicBarrier 让一组线程互相等待到齐后继续，可以重复使用；Semaphore 用许可证控制同时访问的线程数，适合限流。三者解决的问题不同，不要混用。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,死锁,排查', 3, '死锁产生的条件是什么？线上如何排查和避免？', '死锁需要同时满足互斥、持有并等待、不可剥夺、循环等待四个条件。排查可以用 jstack 查看线程状态和锁持有关系，或使用 jconsole、VisualVM。避免思路包括统一加锁顺序、减少锁范围、使用带超时的 tryLock、避免嵌套锁。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,AtomicInteger,LongAdder', 3, 'AtomicInteger 和 LongAdder 有什么区别？', 'AtomicInteger 基于 CAS 更新单个变量，低竞争下性能好；高竞争时 CAS 失败重试增多。LongAdder 把计数分散到多个 Cell，最后求和，适合高并发计数；需要强一致读取时再考虑 AtomicLong。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 并发', '校招', 'Java,并发,虚拟线程,Java21', 3, '什么是虚拟线程？它适合什么场景？', '虚拟线程是 JDK 21 正式引入的轻量级线程，由 JVM 调度，挂载到少量平台线程上；阻塞时会卸载，适合大量 IO 密集型任务。它不适合长时间 CPU 计算，也不能依赖线程池大小做限流，仍需注意同步块导致的 pinning。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,运行时数据区,内存模型', 2, 'JVM 运行时数据区包括哪些部分？哪些是线程共享的？', 'JVM 运行时数据区包括程序计数器、虚拟机栈、本地方法栈、堆和方法区；前三个线程私有，堆和方法区线程共享。程序计数器记录当前字节码位置，虚拟机栈存放栈帧，堆存放对象，方法区存放类元数据；JDK 8 后用元空间实现方法区。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,对象创建,TLAB', 3, 'JVM 创建对象的过程是怎样的？', '对象创建大致经过类加载检查、分配内存、内存零值初始化、设置对象头、执行构造方法。分配方式有指针碰撞和空闲列表，并发时通过 CAS 或 TLAB 保证安全；对象优先在 Eden 分配，大对象可能直接进入老年代。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,对象布局,对象头', 3, 'Java 对象在内存中的布局是怎样的？', '对象在内存中分为对象头、实例数据和对齐填充。对象头包含 Mark Word，保存 hash、GC 年龄、锁状态等信息，还包含类型指针；数组对象还有长度字段。实例数据存放字段，最后按 8 字节对齐填充。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,GC Roots,可达性分析', 2, '什么是 GC Roots？常见的有哪些？', 'GC Roots 是可达性分析的起点，常见包括虚拟机栈中引用的对象、本地方法栈中 Native 方法引用的对象、方法区静态属性引用的对象、方法区常量引用的对象，以及活动线程、类加载器等。从 GC Roots 不可达的对象才可能被回收。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,引用类型,软引用,弱引用', 3, 'Java 的四种引用类型有什么区别？', '强引用只要存在就不会被回收；软引用在内存不足时可能被回收，适合缓存；弱引用在下次 GC 时就会被回收，适合 ThreadLocalMap、WeakHashMap；虚引用不影响对象生命周期，主要用于回收通知和直接内存管理。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,GC算法,标记清除,复制,标记整理', 2, '常见的垃圾回收算法有哪些？各有什么优缺点？', '常见 GC 算法有标记-清除，简单但会产生内存碎片；标记-复制，适合存活率低的新生代，但浪费空间；标记-整理，让存活对象向一端移动，减少碎片，适合老年代。实际 JVM 采用分代收集，不同区域使用不同算法。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,分代收集,Eden,Survivor', 2, 'JVM 的分代收集机制是怎样的？对象如何晋升老年代？', '堆通常分为新生代和老年代，新生代又分 Eden 和两个 Survivor，默认比例 8:1:1。对象优先在 Eden 分配，Minor GC 后存活对象复制到 Survivor 并增加年龄，年龄达到阈值或 Survivor 空间不足时晋升老年代。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,垃圾收集器,G1,ZGC', 3, '常见的垃圾收集器有哪些？G1 有什么特点？', '常见收集器有 Serial、ParNew、Parallel、CMS、G1、ZGC 等。G1 把堆划分为多个 Region，按回收价值优先收集，可以设置预期停顿时间，适合大内存和低延迟场景；ZGC 面向更低延迟和更大堆。选择收集器要结合堆大小、延迟和吞吐量目标。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,MinorGC,FullGC', 3, 'Minor GC 和 Full GC 有什么区别？Full GC 常见触发条件有哪些？', 'Minor GC 只回收新生代，频繁但通常较快；Full GC 回收整个堆和方法区，停顿较长。Full GC 常见触发包括老年代空间不足、元空间不足、显式调用 System.gc()、空间分配担保失败等，线上要重点监控。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,类加载,加载,链接,初始化', 3, '类的加载过程分为哪几个阶段？', '类加载分为加载、链接和初始化。加载读取 class 字节流并生成 Class 对象；链接又分验证、准备、解析，准备阶段给静态变量赋默认值，解析把符号引用替换为直接引用；初始化执行静态变量赋值和静态代码块。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,双亲委派,类加载器', 3, '什么是双亲委派模型？为什么需要它？', '类加载器收到请求时先委派给父加载器，父加载器无法加载时才自己加载。这样可以保证核心类库唯一，防止自定义类覆盖 java.lang 等核心类。Tomcat 等容器为了应用隔离和热部署会打破双亲委派。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,OOM,FullGC,排查', 3, '线上出现 OOM 或频繁 Full GC，你会如何排查？', '可以先用 jps 找进程，jstat 看 GC 频率和各代使用，jstack 看线程，jmap 或 jcmd 导出堆 dump，再用 MAT 或 JVisualVM 分析大对象和引用链。同时结合 GC 日志、监控指标和最近发布变更定位，必要时调整堆大小或对象生命周期。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JVM', '校招', 'Java,JVM,JIT,逃逸分析,锁消除', 3, '什么是 JIT？逃逸分析能带来哪些优化？', 'JVM 先解释执行，热点代码由 JIT 编译为机器码，常见有 C1 快速编译和 C2 优化编译。逃逸分析判断对象是否逃出方法或线程，未逃逸时可以做栈上分配、标量替换和锁消除，减少堆分配和同步开销。', '网络整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
